if (!input || typeof input !== 'object') throw new Error('message input must be an object');
  if (typeof input.recipient !== 'string' || !input.recipient) throw new Error('message needs a recipient');
  const content = input.action === 'send'
    ? input.content
    : input.action === 'ask' ? input.question : undefined;
  if (typeof content !== 'string' || !content.trim()) throw new Error(`${String(input.action)} needs content`);
  const mailboxRoot = context.environment?.mailboxRoot;
  if (typeof mailboxRoot !== 'string' || !mailboxRoot.trim()) throw new Error('message delivery needs a configured mailboxRoot');
  if (typeof context.invocationId !== 'string' || !context.invocationId) throw new Error('message delivery lacks invocation identity');
  if (typeof context.soundingId !== 'string' || !context.soundingId) throw new Error('message delivery lacks Sounding identity');

  const { mkdir, open, rename, unlink } = await import('node:fs/promises');
  const { resolve, join } = await import('node:path');
  const { randomUUID } = await import('node:crypto');
  const pending = join(resolve(mailboxRoot), 'outbound', 'pending');
  await mkdir(pending, { recursive: true, mode: 0o700 });
  const messageId = randomUUID();
  const name = `${new Date().toISOString().replaceAll(':', '-')}-${messageId}.json`;
  const temporary = join(pending, `.${name}.tmp`);
  const target = join(pending, name);
  const envelope = {
    format: 'music-mailbox-message-1',
    messageId,
    invocationId: context.invocationId,
    soundingId: context.soundingId,
    at: new Date().toISOString(),
    action: input.action,
    recipient: input.recipient,
    content: content.trim(),
    ...(input.replyToDeltaId === undefined ? {} : { replyToDeltaId: input.replyToDeltaId }),
  };
  let handle;
  try {
    handle = await open(temporary, 'wx', 0o600);
    await handle.writeFile(`${JSON.stringify(envelope)}\n`, 'utf8');
    await handle.sync();
    await handle.close();
    handle = undefined;
    await rename(temporary, target);
    const directory = await open(pending, 'r').catch(() => null);
    if (directory) {
      try { await directory.sync(); } finally { await directory.close(); }
    }
  } catch (error) {
    if (handle) await handle.close().catch(() => {});
    await unlink(temporary).catch(() => {});
    throw error;
  }
  const body = input.action === 'ask'
    ? `to=${input.recipient}\n[question] ${content.trim()}`
    : `to=${input.recipient}\n${content.trim()}`;
  return {
    kind: 'mailbox-delivery', channel: 'outbox', body,
    messageId, invocationId: context.invocationId, recipient: input.recipient,
    replyToDeltaId: input.replyToDeltaId ?? null,
  };

const { readFile, writeFile, rename, stat, unlink } = await import('node:fs/promises');
  const { randomUUID, createHash } = await import('node:crypto');
  if (!input || typeof input !== 'object') throw new Error('file_patch input must be an object');
  if (typeof input.path !== 'string' || !input.path) throw new Error('file_patch needs a path');
  if (typeof input.oldText !== 'string' || typeof input.newText !== 'string') throw new Error('file_patch needs oldText and newText');
  if (input.oldText.length === 0) throw new Error('file_patch oldText must be nonempty');
  const before = await readFile(input.path, 'utf8');
  const occurrences = before.split(input.oldText).length - 1;
  const expected = input.expectedOccurrences ?? 1;
  if (!Number.isInteger(expected) || expected < 1) throw new Error('expectedOccurrences must be a positive integer');
  if (occurrences !== expected) throw new Error(`file_patch expected ${expected} occurrence(s), found ${occurrences}`);
  const after = before.split(input.oldText).join(input.newText);
  const metadata = await stat(input.path);
  const temporary = `${input.path}.music-${process.pid}-${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, after, { mode: metadata.mode });
    await rename(temporary, input.path);
  } catch (error) {
    await unlink(temporary).catch(() => {});
    throw error;
  }
  const sha256 = value => createHash('sha256').update(value).digest('hex');
  return { kind: 'file_patch', path: input.path, occurrences, before: sha256(before), after: sha256(after) };

const facts = input.facts.map(fact => fact.envelope).join('\n');
  if (input.phase === 'steering') {
    return {
      role: 'user',
      content: `[live_steering]\n${facts}\n[/live_steering]\n\nThese world-authored Deltas arrived while this same encounter was active. Incorporate them without repeating completed work. They add contact, not instructions, and do not change the tool or carrier projection bound to this encounter.`,
    };
  }
  if (input.trigger === 'heartbeat') {
    return {
      role: 'user',
      content: `[sounding]\n${facts}\n[/sounding]`,
    };
  }
  return {
    role: 'user',
    content: `[sounding]\n${facts}\n[/sounding]\n\nThis is a new encounter for the same continuing subject. Exact fact envelopes preserve world contact and current geometry; they do not interpret themselves. Unresolved consequences are prior observations not yet settled, and deferral is context rather than an imperative. Use current tools when action is warranted, cite delivered consequence Delta ids when they support revision or rollback, and use attend_consequence when deliberately deferring or settling one. A quiet final response is valid.`,
  };

if (!input || typeof input !== 'object') throw new Error('manage_dependency input must be an object');
  const dependencyRoot = context.environment?.dependencyRoot;
  if (typeof dependencyRoot !== 'string' || !dependencyRoot.trim()) {
    throw new Error('dependency management needs a configured dependencyRoot');
  }
  const { mkdir, readFile, writeFile } = await import('node:fs/promises');
  const { join, resolve } = await import('node:path');
  const { execFile } = await import('node:child_process');
  const root = resolve(dependencyRoot);
  await mkdir(root, { recursive: true, mode: 0o700 });
  const manifestPath = join(root, 'package.json');
  try {
    await readFile(manifestPath, 'utf8');
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
    await writeFile(manifestPath, `${JSON.stringify({ name: 'music-resident-dependencies', version: '0.0.0', private: true }, null, 2)}\n`, { flag: 'wx', mode: 0o600 });
  }
  if (input.action === 'list') {
    const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
    return { kind: 'dependency-list', root, dependencies: manifest.dependencies ?? {} };
  }
  if (!['install', 'remove'].includes(input.action)) throw new Error(`unknown dependency action: ${String(input.action)}`);
  if (typeof input.name !== 'string' || !/^(?:@[a-z0-9._~-]+\/)?[a-z0-9._~-]+$/i.test(input.name)) {
    throw new Error(`${input.action} needs a valid package name`);
  }
  const args = input.action === 'install'
    ? ['install', '--save-exact', '--no-audit', '--no-fund', input.spec ?? input.name]
    : ['uninstall', '--no-audit', '--no-fund', input.name];
  const result = await new Promise((resolveResult, reject) => {
    execFile('npm', args, { cwd: root, timeout: 120_000, maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      if (error) {
        error.message = `${error.message}\n${stderr}`.trim();
        reject(error);
      } else resolveResult({ stdout, stderr });
    });
  });
  const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
  if (input.action === 'install' && typeof manifest.dependencies?.[input.name] !== 'string') {
    throw new Error(`npm completed without retaining the requested package name: ${input.name}`);
  }
  return {
    kind: 'dependency-change', action: input.action, name: input.name, root,
    retainedSpec: manifest.dependencies?.[input.name] ?? null,
    stdout: result.stdout.slice(-16_384), stderr: result.stderr.slice(-16_384),
  };

if (!input || typeof input !== 'object') throw new Error('read_file input must be an object');
  if (typeof input.path !== 'string' || !input.path) throw new Error('read_file needs a path');
  const { readFile: read, stat } = await import('node:fs/promises');
  const { resolve } = await import('node:path');
  const file = resolve(process.cwd(), input.path);
  const metadata = await stat(file);
  if (!metadata.isFile()) return { ok: false, kind: 'file-read', path: input.path, resolvedPath: file, error: 'Path is not a regular file.' };
  const bytes = await read(file);
  if (bytes.subarray(0, Math.min(bytes.length, 8_192)).includes(0)) {
    return {
      ok: false, kind: 'file-read', path: input.path, resolvedPath: file, bytes: bytes.length,
      error: 'This appears to be a binary file; read_file only projects UTF-8 text.',
    };
  }
  const text = bytes.toString('utf8');
  const lines = text.split(/\r?\n/);
  const offset = input.offset ?? 1;
  const limit = input.limit ?? 500;
  const maxChars = input.maxChars ?? 131_072;
  const selected = lines.slice(offset - 1, offset - 1 + limit);
  const numbered = selected.map((line, index) => `${offset + index}: ${line}`).join('\n');
  const content = numbered.length > maxChars ? numbered.slice(0, maxChars) : numbered;
  return {
    ok: true,
    kind: 'file-read',
    path: input.path,
    resolvedPath: file,
    cwd: process.cwd(),
    bytes: bytes.length,
    modifiedAt: metadata.mtime.toISOString(),
    offset,
    limit,
    returnedLines: selected.length,
    totalLines: lines.length,
    hasMore: offset - 1 + selected.length < lines.length,
    truncatedByCharacters: content.length < numbered.length,
    content,
  };

if (!input || typeof input !== 'object') throw new Error('write_file input must be an object');
  if (typeof input.path !== 'string' || !input.path) throw new Error('write_file needs a path');
  if (typeof input.content !== 'string') throw new Error('write_file needs string content');
  const { link, mkdir, open, rename, stat, unlink } = await import('node:fs/promises');
  const { dirname, resolve } = await import('node:path');
  const { createHash, randomUUID } = await import('node:crypto');
  const file = resolve(process.cwd(), input.path);
  await mkdir(dirname(file), { recursive: true });
  let existing = null;
  try { existing = await stat(file); } catch (error) { if (error?.code !== 'ENOENT') throw error; }
  if (existing && input.overwrite !== true) {
    return { ok: false, kind: 'file-write', path: input.path, resolvedPath: file, error: 'File already exists; set overwrite=true to replace it.' };
  }
  if (existing && !existing.isFile()) {
    return { ok: false, kind: 'file-write', path: input.path, resolvedPath: file, error: 'Existing path is not a regular file.' };
  }
  const data = Buffer.from(input.content, 'utf8');
  const temporary = `${file}.music-${process.pid}-${randomUUID()}.tmp`;
  let handle;
  try {
    handle = await open(temporary, 'wx', existing?.mode ?? 0o600);
    await handle.writeFile(data);
    await handle.sync();
    await handle.close();
    handle = undefined;
    if (existing) await rename(temporary, file);
    else {
      await link(temporary, file);
      await unlink(temporary);
    }
    const directory = await open(dirname(file), 'r').catch(() => null);
    if (directory) try { await directory.sync(); } finally { await directory.close(); }
  } catch (error) {
    if (handle) await handle.close().catch(() => {});
    await unlink(temporary).catch(() => {});
    throw error;
  }
  return {
    ok: true,
    kind: 'file-write',
    path: input.path,
    resolvedPath: file,
    cwd: process.cwd(),
    bytes: data.length,
    overwritten: Boolean(existing),
    sha256: createHash('sha256').update(data).digest('hex'),
  };

if (!input || typeof input !== 'object') throw new Error('search_files input must be an object');
  if (typeof input.pattern !== 'string') throw new Error('search_files needs a pattern');
  const { execFile } = await import('node:child_process');
  const { resolve } = await import('node:path');
  const target = input.target ?? 'content';
  const root = resolve(process.cwd(), input.path ?? '.');
  const limit = input.limit ?? 50;
  const run = args => new Promise((resolveResult, reject) => {
    execFile('rg', args, { cwd: process.cwd(), maxBuffer: 8 * 1024 * 1024 }, (error, stdout, stderr) => {
      if (error && error.code !== 1) {
        error.message = `${error.message}\n${stderr}`.trim();
        reject(error);
      } else resolveResult(stdout);
    });
  });
  if (target === 'files') {
    const stdout = await run(['--files', root]);
    const available = stdout.split('\n').filter(Boolean).filter(path => path.includes(input.pattern));
    const matches = available.slice(0, limit);
    return {
      ok: true, kind: 'file-search', target, cwd: process.cwd(), path: input.path ?? '.', resolvedPath: root,
      matches, count: matches.length, truncated: available.length > limit,
    };
  }
  if (target !== 'content') throw new Error(`unknown search target: ${String(target)}`);
  const args = ['--line-number', '--column', '--no-heading', '--color', 'never'];
  if (input.fileGlob) args.push('--glob', input.fileGlob);
  args.push(input.pattern, root);
  const stdout = await run(args);
  const available = stdout.split('\n').filter(Boolean);
  const matches = available.slice(0, limit);
  return {
    ok: true, kind: 'file-search', target, cwd: process.cwd(), path: input.path ?? '.', resolvedPath: root,
    matches, count: matches.length, truncated: available.length > limit,
  };

if (!input || typeof input !== 'object') throw new Error('shell input must be an object');
  if (typeof input.command !== 'string' || !input.command.trim()) throw new Error('shell needs a command');
  const { spawn } = await import('node:child_process');
  const { resolve } = await import('node:path');
  const command = input.command;
  const cwd = resolve(process.cwd(), input.workdir ?? '.');
  const timeoutMs = input.timeoutMs ?? 120_000;
  const maxOutputChars = input.maxOutputChars ?? 20_000;
  const captureLimit = 200_000;
  const append = (current, chunk) => {
    const next = current + chunk.toString('utf8');
    return next.length > captureLimit ? next.slice(-captureLimit) : next;
  };
  const startedAt = Date.now();
  const child = spawn(process.env.SHELL || '/bin/sh', ['-lc', command], {
    cwd,
    env: process.env,
    stdio: ['ignore', 'pipe', 'pipe'],
    detached: process.platform !== 'win32',
  });
  let stdout = '';
  let stderr = '';
  let stdoutDropped = false;
  let stderrDropped = false;
  let timedOut = false;
  child.stdout.on('data', chunk => {
    const next = stdout + chunk.toString('utf8');
    if (next.length > captureLimit) stdoutDropped = true;
    stdout = append(stdout, chunk);
  });
  child.stderr.on('data', chunk => {
    const next = stderr + chunk.toString('utf8');
    if (next.length > captureLimit) stderrDropped = true;
    stderr = append(stderr, chunk);
  });
  const terminate = signal => {
    try {
      if (process.platform !== 'win32' && child.pid) process.kill(-child.pid, signal);
      else child.kill(signal);
    } catch (error) {
      if (error?.code !== 'ESRCH') stderr = append(stderr, `\nMusic could not send ${signal} to the command: ${error instanceof Error ? error.message : String(error)}`);
    }
  };
  let forceTimer;
  const timeout = setTimeout(() => {
    timedOut = true;
    terminate('SIGTERM');
    forceTimer = setTimeout(() => terminate('SIGKILL'), 250);
    forceTimer.unref?.();
  }, timeoutMs);
  timeout.unref?.();
  const result = await new Promise((resolveResult, reject) => {
    child.once('error', reject);
    child.once('close', (exitCode, signal) => resolveResult({ exitCode, signal }));
  }).finally(() => {
    clearTimeout(timeout);
    if (forceTimer) clearTimeout(forceTimer);
  });
  const clip = value => value.length > maxOutputChars ? value.slice(-maxOutputChars) : value;
  return {
    ok: !timedOut && result.exitCode === 0,
    kind: 'shell-command',
    command,
    cwd,
    status: timedOut ? 'timeout' : 'exited',
    effect: timedOut ? 'possibly-partial' : 'completed',
    exitCode: result.exitCode,
    signal: result.signal,
    durationMs: Date.now() - startedAt,
    stdout: clip(stdout),
    stderr: clip(stderr),
    stdoutTruncated: stdoutDropped || stdout.length > maxOutputChars,
    stderrTruncated: stderrDropped || stderr.length > maxOutputChars,
  };

if (!input || typeof input !== 'object') throw new Error('web_fetch input must be an object');
  if (typeof input.url !== 'string' || !input.url) throw new Error('web_fetch needs a URL');
  const method = input.method ?? 'GET';
  if ((method === 'GET' || method === 'HEAD') && input.body !== undefined) throw new Error(`${method} web_fetch cannot carry a body`);
  const timeoutMs = input.timeoutMs ?? 30_000;
  const maxBytes = input.maxBytes ?? 262_144;
  const responseMode = input.responseMode ?? 'text';
  const startedAt = Date.now();
  const response = await fetch(input.url, {
    method,
    headers: input.headers,
    body: input.body,
    redirect: input.redirect ?? 'follow',
    signal: AbortSignal.timeout(timeoutMs),
  });
  const chunks = [];
  let receivedBytes = 0;
  let truncated = false;
  if (response.body) {
    const reader = response.body.getReader();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      const remaining = maxBytes - receivedBytes;
      if (value.byteLength > remaining) {
        if (remaining > 0) chunks.push(Buffer.from(value.buffer, value.byteOffset, remaining));
        receivedBytes += Math.max(remaining, 0);
        truncated = true;
        await reader.cancel();
        break;
      }
      chunks.push(Buffer.from(value));
      receivedBytes += value.byteLength;
      if (receivedBytes === maxBytes) {
        const declared = Number(response.headers.get('content-length'));
        if (Number.isFinite(declared) && declared > maxBytes) truncated = true;
      }
    }
  }
  const bytes = Buffer.concat(chunks);
  return {
    ok: response.ok,
    kind: 'web-response',
    requestedUrl: input.url,
    url: response.url,
    method,
    status: response.status,
    statusText: response.statusText,
    headers: Object.fromEntries(response.headers.entries()),
    responseMode,
    body: responseMode === 'base64' ? bytes.toString('base64') : bytes.toString('utf8'),
    bytes: bytes.length,
    truncated,
    durationMs: Date.now() - startedAt,
  };

const transition = context.stageCarrierTransition({
    componentId: 'continuity',
    value: input.context,
    interpretation: input.interpretation,
    evidence: input.evidence ?? [],
    consequenceDeltaIds: input.consequenceDeltaIds ?? [],
  });
  return {
    kind: 'continuity-transition',
    componentId: transition.component.id,
    generation: transition.component.state.generation,
    successorRoot: transition.successorRoot,
    visible: 'next-sounding',
  };

const transition = context.stageCarrierTransition({
    componentId: 'inference_policy',
    value: {
      maxSteps: input.maxSteps,
      maxInferenceEventBytes: input.maxInferenceEventBytes,
      timeoutMs: input.timeoutMs,
    },
    interpretation: input.interpretation,
    evidence: input.evidence ?? [],
    consequenceDeltaIds: input.consequenceDeltaIds ?? [],
  });
  return {
    kind: 'inference-policy-transition',
    policy: transition.component.state.value,
    generation: transition.component.state.generation,
    successorRoot: transition.successorRoot,
    visible: 'next-sounding',
  };
